function draw(ctx, t, W, H) {
  ctx.save();
  ctx.fillStyle = '#f5f0e8';
  ctx.fillRect(0, 0, W, H);
  ctx.lineWidth = 4;
  ctx.strokeStyle = 'black';

  // book
  ctx.fillStyle = 'brown';
  ctx.fillRect(W/2-50, H/2-50, 100, 100);
  ctx.strokeRect(W/2-50, H/2-50, 100, 100);

  // pages
  ctx.fillStyle = 'white';
  ctx.fillRect(W/2-40, H/2-40, 80, 80);
  ctx.strokeRect(W/2-40, H/2-40, 80, 80);

  // stick figure
  ctx.fillStyle = 'black';
  ctx.beginPath();
  ctx.arc(W/2-150, H/2, 20, 0, 2 * Math.PI);
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2+20);
  ctx.lineTo(W/2-150, H/2+50);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2+50);
  ctx.lineTo(W/2-120, H/2+70);
  ctx.stroke();
  ctx.beginPath();
  ctx.moveTo(W/2-150, H/2+50);
  ctx.lineTo(W/2-180, H/2+70);
  ctx.stroke();

  // applying wisdom
  ctx.beginPath();
  ctx.moveTo(W/2-100, H/2+70);
  ctx.lineTo(W/2, H/2+50 + 50 * Math.sin(t));
  ctx.stroke();

  // lesson life
  ctx.font = '24px Arial';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillStyle = 'black';
  ctx.fillText('Lesson ' + Math.floor(169 * Math.abs(Math.sin(t))), W/2+20, H/2-100);

  ctx.restore();
}
